class P:
    def __init__(self, x):
        self.x = x
    def __eq__(self, o):
        return isinstance(o, P) and self.x == o.x
    def __lt__(self, o):
        return self.x < o.x
    def __repr__(self):
        return f'P({self.x})'

print(P(1) == P(1))
print(sorted([P(3), P(1), P(2)]))

